const equipmentCategories=UTL.CATEGORIES;
const attrs=['Strength','Coordination','Willpower','Focus','Endurance','Quickness'];
const short={Strength:'STR',Coordination:'COORD',Willpower:'WILL',Focus:'FOCUS',Endurance:'END',Quickness:'QUICK'};
const tiers=['Minor','Major','Epic','Legendary'];
const sets=['Adept','Defender','Dexterous','Hearty','Dedication','Flame Proof','Acid Proof','Cold Proof','Lightning Proof'];
const groups={Attributes:attrs,'Magic & summoning':DATA.spells.filter(s=>/Magic Aptitude|Enchantment Aptitude|Mana Conversion|Summoning/.test(s)),'Weapons & combat':DATA.spells.filter(s=>/Weapon Aptitude|Combat Aptitude|Dual Wield|Dirty Fighting|Recklessness|Shield Aptitude|Sneak Attack/.test(s)),Wards:DATA.spells.filter(s=>/ Ward$/.test(s)),Defense:DATA.spells.filter(s=>/Invulnerability|Impregnability|Magic Resistance|^Armor$/.test(s)),'Armor banes':DATA.spells.filter(s=>/ Bane$|^Impenetrability$/.test(s))};
groups['Crafting & other skills']=DATA.spells.filter(s=>!Object.values(groups).flat().includes(s));
function allowedSpell(category,spell){return DATA.spells.includes(spell)&&!(['Jewelry','Trinkets','Cloaks'].includes(category)&&attrs.includes(spell))&&(!/ Bane$|^Impenetrability$/.test(spell)||category==='Armor')}
function cantripGroups(category){return Object.entries(groups).map(([name,values])=>[name,values.filter(s=>allowedSpell(category,s))]).filter(([,values])=>values.length)}
// Selected spells are positive minimum requirements. Unselected extra spells never veto a match.
function matchesCantripRequirement(t,itemCantrips){if(!t.enabled)return false;if(t.count===0)return true;if(!t.spells.length||!t.tiers.length)return false;const matches=itemCantrips.filter(c=>t.spells.includes(c.name)&&t.tiers.includes(c.tier));return matches.length>=t.count}
function selectSuggested(){target().spells=[...new Set([...target().spells,...(['Jewelry','Trinkets'].includes(tab)?groups.Wards:attrs)])];persist();render()}
function fresh(name,category='Armor'){let t=UTL.ratingDefaults({name,enabled:true,tiers:['Legendary'],spells:[...attrs],count:1,sets:[]});if(category==='Armor')t.cd=2;else if(category==='Underclothes')t.damage=3;else if(category==='Cloaks'){t.count=0;t.spells=[];t.cloakLevel=5;t.cloakSet=0;t.cloakProc='any'}else {t.spells=[...groups.Wards];if(category==='Trinkets'){t.count=0;t.spells=[];t.vitality=3}}return t}
let state={Underclothes:[fresh('Legendary attributes · D3','Underclothes')],Armor:[{...fresh('Adept / Defender · attributes'),sets:['Adept','Defender'],cdr:2}],Jewelry:[{...fresh('Legendary wards & magic','Jewelry'),spells:[...groups.Wards,'War Magic Aptitude','Void Magic Aptitude']}],Trinkets:[{...fresh('Health or healing','Trinkets'),enabled:false}],Cloaks:[{...fresh('Level 5 cloak','Cloaks'),enabled:false}],materials:structuredClone(DATA.materials),reserve:5,custom:true,quantity:0,weaponPreset:'LegendaryPlus',weapons:structuredClone(DATA.profiles.LegendaryPlus)},tab='Underclothes',selected=0,spellQuery='',weaponQuery='';
try{let old=JSON.parse(localStorage.getItem('noobloot-preview-v2')||localStorage.getItem('lootwork-preview'));if(old){state={...state,...old};if(!old.Cloaks)state.Cloaks=[{...fresh('Level 5 cloak','Cloaks'),enabled:false}];if(!old.Trinkets&&Array.isArray(old.Jewelry))state.Trinkets=structuredClone(old.Jewelry).map(t=>({...t,name:t.name+' · legacy trinkets'}));for(const cat of equipmentCategories)state[cat]=state[cat].map(t=>UTL.ratingDefaults({...t,spells:t.spells||t.attrs?.map(a=>Object.keys(short).find(s=>short[s]===a)||a)||[...attrs]}))}}catch(e){}
for(const category of equipmentCategories)for(const t of state[category])t.spells=t.spells.filter(s=>allowedSpell(category,s));
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
function persist(){try{localStorage.setItem('noobloot-preview-v2',JSON.stringify(state))}catch(e){document.getElementById('storageNote')?.remove();document.getElementById('main').insertAdjacentHTML('beforeend','<p id="storageNote">Browser storage is unavailable. Download your settings to retain changes.</p>')}}
function target(){return state[tab][selected]}
function display(s){return short[s]||s}
function checks(values,current,key){return '<div class="choices">'+values.map(x=>`<label><input type="checkbox" ${current.includes(x)?'checked':''} data-key="${key}" data-value="${esc(x)}" onchange="toggle(this.dataset.key,this.dataset.value,this.checked)"> ${esc(display(x))}</label>`).join('')+'</div>'}
function toggle(key,value,on){if(key==='spells'&&!allowedSpell(tab,value))return;let a=target()[key];if(on&&!a.includes(value))a.push(value);else if(!on&&a.includes(value))a.splice(a.indexOf(value),1);persist();refreshSummary();if(key==='spells')refreshCounts()}
function update(key,value){target()[key]=value;persist();refreshSummary();if(key==='name'||key==='enabled')render()}
function number(v,min=0,max=100){return Math.min(max,Math.max(min,Math.trunc(Number(v))||min))}
function ratingControls(t){const primary=UTL.primaryRatings(tab),other=Object.keys(UTL.RATINGS).filter(k=>!primary.includes(k));function control(k,extra=false){let r=UTL.RATINGS[k],value=t[k]||0,values=[...Array(r.referenceMax+1).keys()];if(value>r.referenceMax)values.push(value);return `<label>${esc(r.label)} (${r.short}) ${extra?`<input aria-label="Minimum ${r.label}" type="number" min="0" max="100" value="${value}" onchange="this.value=number(this.value,0,100);update('${k}',+this.value)">`:`<select aria-label="Minimum ${r.label}" onchange="update('${k}',+this.value)">${values.map(v=>`<option value="${v}" ${value===v?'selected':''}>${v===0?'Unused':'≥ '+v}</option>`).join('')}</select>`}</label>`}return `<div class="field"><span>Minimum ratings · any selected rating may qualify</span><div class="row">${primary.map(k=>control(k)).join('')}</div><p class="muted">Tier 8 reference: up to ${UTL.RATINGS[primary[0]].referenceMax}. Higher rolls also qualify. With no ratings selected, any rating is accepted.</p><details class="spellgroup" ${other.some(k=>t[k]>0)?'open':''}><summary>Extra server ratings</summary><p class="muted">Optional custom-server and legacy settings. Each selected rating is an alternative.</p><div class="row">${other.map(k=>control(k,true)).join('')}</div></details></div>`}
function summary(t){let ratings=Object.entries(UTL.RATINGS).filter(([k])=>t[k]>0).map(([k,r])=>r.short+' ≥ '+t[k]).join(' or ')||'any rating';let spells=t.count===0?'no cantrip requirement':`at least ${t.count} matching cantrip${t.count>1?'s':''} from ${t.tiers.join(' / ')||'[choose a tier]'}: ${t.spells.map(display).join(', ')||'[choose cantrips]'}`;return `${t.enabled?'Keep':'Disabled target: would keep'} ${tab.toLowerCase()}${tab==='Armor'?' from '+(t.sets.length?t.sets.join(' or '):'any set'):''} ${tab==='Cloaks'?cloakSummary(t):''} with ${ratings}, and ${spells}. Additional cantrips are welcome and do not disqualify the item. Preserve ${state.reserve} free main-pack spaces.`}
function refreshSummary(){let t=target(),node=document.getElementById('targetSummary');if(node)node.textContent=summary(t);let issue=t.count>0&&(!t.spells.length||!t.tiers.length||t.count>t.spells.length*t.tiers.length);let warning=document.getElementById('targetWarning');if(warning)warning.textContent=issue?'Choose tiers and enough distinct cantrips to satisfy this target.':''}
function refreshCounts(){document.querySelectorAll('[data-count]').forEach(n=>{let options=groups[n.dataset.count];n.textContent=options.filter(s=>target().spells.includes(s)).length+' selected'})}
function groupSelect(name,on){let values=groups[name].filter(s=>allowedSpell(tab,s));if(on)target().spells=[...new Set([...target().spells,...values])];else target().spells=target().spells.filter(s=>!values.includes(s));persist();render()}
function spellPanel(t){return `<input class="spellsearch" aria-label="Search cantrips" placeholder="Search cantrips · war, void, ward, strength…" value="${esc(spellQuery)}" oninput="filterSpells(this.value)"><div class="row"><button onclick="selectSuggested()">${['Jewelry','Trinkets'].includes(tab)?'All wards':'All attributes'}</button><button onclick="target().spells=[];persist();render()">Clear cantrips</button></div>`+cantripGroups(tab).map(([name,values])=>`<details class="spellgroup" data-group="${esc(name)}" ${name==='Attributes'||['Jewelry','Trinkets'].includes(tab)&&['Magic & summoning','Wards'].includes(name)?'open':''}><summary>${esc(name)}<span class="count" data-count="${esc(name)}">${values.filter(s=>t.spells.includes(s)).length} selected</span></summary><div class="row" style="margin-top:10px"><button data-group="${esc(name)}" onclick="groupSelect(this.dataset.group,true)">Select group</button><button data-group="${esc(name)}" onclick="groupSelect(this.dataset.group,false)">Clear group</button></div><div class="choices">${values.map(s=>`<label data-spell="${esc((s+' '+display(s)).toLowerCase())}"><input type="checkbox" data-value="${esc(s)}" ${t.spells.includes(s)?'checked':''} onchange="toggle('spells',this.dataset.value,this.checked)"> ${esc(display(s))}</label>`).join('')}</div></details>`).join('')+'<p id="noSpellResults" class="muted" hidden>No matching cantrips.</p>'}
function filterSpells(q){spellQuery=q;let visible=0;document.querySelectorAll('[data-spell]').forEach(n=>n.hidden=!n.dataset.spell.includes(q.toLowerCase()));document.querySelectorAll('details[data-group]').forEach(d=>{let has=[...d.querySelectorAll('[data-spell]')].some(n=>!n.hidden);d.hidden=!has;if(has)visible++;if(q&&has)d.open=true});let n=document.getElementById('noSpellResults');if(n)n.hidden=!!visible}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let subtitle=tab==='Salvage'?'Choose materials, item workmanship, and bag combination ranges.':tab==='Settings'?'Shared limits for the entire profile.':tab==='Weapons'?'Editable damage thresholds from your DreamWeave profiles.':'Matching any enabled target keeps the item.';let html=`<div class="top"><div><h2>${tab==='Weapons'?'Weapons & wands':tab}</h2><span class="muted">${subtitle}</span></div></div>`;
if(tab==='Profile'){html+=profilePanel();}else if(tab==='DreamWeave'){html+=serverPanel();}else if(tab==='Imported'){html+=importedPanel();}else if(equipmentCategories.includes(tab)){let t=target();html+=`<div class="layout"><div class="card targets"><h3>Your targets</h3>${state[tab].map((x,i)=>`<button class="${i===selected?'selected':''}" onclick="selected=${i};spellQuery='';render()">${esc(x.name)}${x.enabled?'':' · Off'}</button>`).join('')}<button class="primary" onclick="addTarget()">+ Add target</button></div><div class="card"><div class="row"><label><input type="checkbox" ${t.enabled?'checked':''} onchange="update('enabled',this.checked)"> Enabled</label><button onclick="duplicate()">Duplicate</button>${state[tab].length>1?'<button onclick="remove()">Delete target</button>':''}</div><br><label class="field"><span>Target name</span><input style="width:100%" value="${esc(t.name)}" onchange="update('name',this.value)"></label>`;
if(tab==='Cloaks')html+=cloakControls(t);
if(tab==='Armor')html+=`<div class="field"><span>Sets · no selection means any set</span>${checks(sets,t.sets,'sets')}</div>`;
html+=`<div class="ratings">${ratingControls(t)}${tab==='Cloaks'?'</div><p class="muted">Cloak set and proc requirements are independent of cantrip tiers.</p>':`<div class="field"><span>Accepted cantrip tiers · choose any combination</span>${checks(tiers,t.tiers,'tiers')}</div><label class="field"><span>Minimum matching cantrips · 0 ignores cantrips</span><input type="number" min="0" max="100" value="${t.count}" onchange="this.value=number(this.value,0,100);update('count',+this.value)"></label></div><h3>Wanted cantrips</h3><p class="muted">These are minimum requirements. Extra cantrips are always allowed—even if they are not selected here.</p>${spellPanel(t)}`}<p class="empty" id="targetWarning"></p><div class="summary" id="targetSummary"></div></div></div>`;
}else if(tab==='Weapons'){html+=weaponPanel();
}else if(tab==='Salvage'){html+=`<div class="card"><div class="row"><input placeholder="Search materials" oninput="filterMaterials(this.value)" aria-label="Search materials"><button onclick="bulk()">Apply ranges to enabled materials</button></div><p class="muted">Material names and descriptions come from your DreamWeave profile. Item ranges are editable examples, not an imported UTL.</p><div class="tablewrap"><table><thead><tr><th>USE</th><th>MATERIAL / PURPOSE</th><th>ITEM MIN</th><th>ITEM MAX</th><th>COMBINE BAGS IN RANGES</th></tr></thead><tbody>${state.materials.map((m,i)=>`<tr data-material="${esc(m.name.toLowerCase())}"><td><input aria-label="Enable ${esc(m.name)}" type="checkbox" ${m.enabled?'checked':''} onchange="mat(${i},'enabled',this.checked)"></td><td>${esc(m.name)}<small>${esc(m.description)}</small></td><td><input aria-label="${esc(m.name)} minimum workmanship" type="number" min="1" max="10" value="${m.minimum}" onchange="mat(${i},'minimum',+this.value)"></td><td><input aria-label="${esc(m.name)} maximum workmanship" type="number" min="1" max="10" value="${m.maximum}" onchange="mat(${i},'maximum',+this.value)"></td><td><input aria-label="${esc(m.name)} combine ranges" type="text" value="${esc(m.combine)}" onchange="mat(${i},'combine',this.value)"></td></tr>`).join('')}</tbody></table></div></div>`;
}else{html+=`<div class="card"><h3>Keep room to function</h3><label class="field"><span>Free main-pack spaces to preserve</span><input type="number" min="0" value="${state.reserve}" onchange="this.value=number(this.value,0,1000);state.reserve=+this.value;persist()"></label><p class="muted">Applies to equipment, salvage, and DreamWeave custom items.</p></div><div class="card"><h3>DreamWeave custom items</h3><label><input type="checkbox" ${state.custom?'checked':''} onchange="state.custom=this.checked;persist()"> Retain custom items by default</label><label class="field" style="margin-top:20px"><span>Default keep quantity · 0 means Keep all</span><input type="number" min="0" value="${state.quantity}" onchange="this.value=number(this.value,0,999999);state.quantity=+this.value;state.serverItems.forEach(e=>e.quantity=state.quantity);persist()"></label><p class="muted">Individual item toggles and quantities are available under DreamWeave items.</p></div>`}document.getElementById('main').innerHTML=html+'<footer>BroLoot · Version 1.2 · Loot profile editor</footer>';if(equipmentCategories.includes(tab)){refreshSummary();filterSpells(spellQuery)}if(tab==='Weapons')filterWeapons(weaponQuery);if(tab==='Imported')filterImported(importQuery)}
function addTarget(){state[tab].push(fresh('New target',tab));selected=state[tab].length-1;spellQuery='';persist();render()}
function duplicate(){state[tab].push({...structuredClone(target()),name:target().name+' copy'});selected=state[tab].length-1;persist();render()}
function remove(){state[tab].splice(selected,1);selected=0;persist();render()}
function clearDamageCaps(){state.weapons.forEach(w=>w.maximum='');persist();render()}
function weaponPanel(){return `${state.weapons.some(w=>w.maximum!==''&&w.maximum!=null)?'<div class="imported-summary">Earlier preview settings contain upper damage caps. The UTL engine supports minimum buffed damage thresholds. <button onclick="clearDamageCaps()">Remove old upper caps</button></div>':''}<div class="card"><div class="weaponhead"><label>Starting profile <select onchange="preset(this.value)">${Object.keys(DATA.profiles).map(p=>`<option ${state.weaponPreset===p?'selected':''}>${esc(p)}</option>`).join('')}</select></label><input aria-label="Search weapon types" placeholder="Search · sword, bow, war…" value="${esc(weaponQuery)}" oninput="filterWeapons(this.value)"><button onclick="resetWeapons()">Reset damage defaults</button></div><p>Minimums use the profiles’ effective damage values, including their applicable cantrip calculations. Higher damage qualifies automatically.</p><p class="muted">Every wield tier remains available. “Top tier” retains the final rule in the original profile, which has no explicit wield requirement. Wands use elemental multipliers, not melee damage units.</p><div class="tablewrap"><table><thead><tr><th>USE</th><th>TYPE / SOURCE</th><th>WIELD TIER</th><th>EFFECTIVE MIN</th><th>MEASURE</th></tr></thead><tbody>${state.weapons.map((w,i)=>`<tr data-weapon="${esc((w.family+' '+w.kind).toLowerCase())}"><td><input aria-label="Enable ${esc(w.source)}" type="checkbox" ${w.enabled?'checked':''} onchange="weapon(${i},'enabled',this.checked)"></td><td>${esc(({H:'Heavy',L:'Light',F:'Finesse','2H':'Two-handed',M:'Missile',W:'Wand'})[w.family])} · ${esc(w.kind)}<small>Profile default: OD +${w.od}</small></td><td>${esc(w.wield)}</td><td><input aria-label="${esc(w.source)} minimum damage" type="number" min="0" step="0.01" value="${w.minimum}" onchange="weapon(${i},'minimum',this.value)"></td><td>${esc(w.unit)}</td></tr>`).join('')}</tbody></table></div><p id="weaponEmpty" class="muted" hidden>No weapon types match your search.</p><div class="summary">These are editable profile thresholds, not a live item tester. Changing a threshold overrides that row’s starting OD example.</div></div>`}
function filterWeapons(q){weaponQuery=q;let visible=0;document.querySelectorAll('[data-weapon]').forEach(r=>{r.hidden=!r.dataset.weapon.includes(q.toLowerCase());if(!r.hidden)visible++});let n=document.getElementById('weaponEmpty');if(n)n.hidden=!!visible}
function preset(p){if(!DATA.profiles[p])return;if(!confirm('Replace weapon thresholds with '+p+' defaults? Other categories will stay as they are.')){render();return}state.weaponPreset=p;state.weapons=structuredClone(DATA.profiles[p]);persist();render()}
function resetWeapons(){preset(state.weaponPreset)}
function weapon(i,k,v){let w=state.weapons[i];if(k!=='enabled'){if(v===''&&k==='maximum'){}else{v=Number(v);if(!Number.isFinite(v)||v<0){alert('Use a non-negative damage value.');render();return}}if(k==='maximum'&&v!==''&&v<w.minimum||k==='minimum'&&w.maximum!==''&&v>w.maximum){alert('Maximum damage must be at least the minimum, or left blank.');render();return}}w[k]=v;persist()}
function mat(i,k,v){let m=state.materials[i];if(k==='minimum'||k==='maximum'){if(v<1||v>10||!Number.isInteger(v)||(k==='minimum'?v>m.maximum:v<m.minimum)){alert('Use a workmanship range between 1 and 10, with minimum no greater than maximum.');render();return}}if(k==='combine'&&!validRanges(v)){alert('Ranges must be ordered, non-overlapping, and between 1 and 10.');render();return}m[k]=v;persist()}
function validRanges(v){if(!/^\s*\d+(?:\s*[-–]\s*\d+)?(?:\s*,\s*\d+(?:\s*[-–]\s*\d+)?)*\s*$/.test(v))return false;let last=0;return v.split(',').every(part=>{let a=part.trim().split(/[-–]/).map(Number),lo=a[0],hi=a.length===1?lo:a[1];if(lo<1||hi>10||lo>hi||lo<=last)return false;last=hi;return true})}
function filterMaterials(q){document.querySelectorAll('[data-material]').forEach(r=>r.hidden=!r.dataset.material.includes(q.toLowerCase()))}
function bulk(){let enabled=state.materials.filter(m=>m.enabled);if(!enabled.length){alert('Enable the materials you want to edit first.');return}let v=prompt('Combination ranges for all '+enabled.length+' enabled materials','1–6, 7–8, 9, 10');if(v!==null){if(!validRanges(v)){alert('Use ordered ranges between 1 and 10.');return}enabled.forEach(m=>m.combine=v);persist();render()}}
function save(){const b=new Blob([JSON.stringify({format:'BroLoot preview',version:3,cantripMatching:'minimum-selected-extra-allowed',...state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='BroLoot-preview-settings.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
initIO();
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;selected=0;spellQuery='';render()});render();
